import{c as s,$ as e,Q as r,j as i,g as a,o as n,n as o,m as d}from"./chunks/framework.Ce_49mA8.js";const y=JSON.parse('{"title":"Аналитика и валютная корзина","description":"Практическое руководство по аналитике личного капитала мастера, защите активов через валютную корзину, балансировке 4 классов фондов и сохранению финансовой ретроспективы в ОмниКрафт ЕРП.","frontmatter":{"title":"Аналитика и валютная корзина","description":"Практическое руководство по аналитике личного капитала мастера, защите активов через валютную корзину, балансировке 4 классов фондов и сохранению финансовой ретроспективы в ОмниКрафт ЕРП.","datePublished":"2026-10-28","dateModified":"2026-11-19","order":20},"headers":[],"relativePath":"ru/docs/spaces/moy-kapital/analytics.md","filePath":"ru/docs/spaces/moy-kapital/analytics.md","lastUpdated":1795046400000}'),c={name:"ru/docs/spaces/moy-kapital/analytics.md"},p={id:"аналитика-и-валютная-корзина-стратегическии-контроль-благосостояния",tabindex:"-1"};function h(g,t,b,u,f,v){const l=e("DocIcon");return r(),i("div",null,[a("h1",p,[n(l,{name:"capital"}),t[0]||(t[0]=o(" Аналитика и валютная корзина: Стратегический контроль благосостояния ",-1)),t[1]||(t[1]=a("a",{class:"header-anchor",href:"#аналитика-и-валютная-корзина-стратегическии-контроль-благосостояния","aria-label":'Permalink to "Аналитика и валютная корзина: Стратегический контроль благосостояния"'},"​",-1))]),t[2]||(t[2]=d('<p>Пока операционные экраны — касса движения денег мастерской или реестр банковских счетов — отвечают на сиюминутный вопрос <em>«Сколько свободных средств доступно прямо сейчас»</em>, аналитический контур пространства «Мой капитал» решает принципиально иную инженерную задачу. Он дает мастеру долгосрочный стратегический ответ: <strong>насколько надежно совокупное благосостояние защищено от девальваций, инфляционных шоков и кризисов, и сохраняется ли устойчивый многолетний рост семейных ресурсов</strong>.</p><p>В программе реализовано два взаимодополняющих инструмента финансовой аналитики:</p><ul><li><strong>Оперативный виджет «Статистика капитала»:</strong> вызывается в один клик с верхней панели счетов и инвестиций для мгновенного контроля валютной диверсификации и баланса фондов;</li><li><strong>Стратегическая вкладка «Аналитика»:</strong> пятый элемент верхней воронки навигации, предназначенный для отслеживания многолетних трендов чистого капитала и мониторинга темпа бытовых расходов семьи.</li></ul><hr><h2 id="виджет-статистики-капитала-структура-активов-в-один-клик" tabindex="-1">Виджет статистики капитала: структура активов в один клик <a class="header-anchor" href="#виджет-статистики-капитала-структура-активов-в-один-клик" aria-label="Permalink to &quot;Виджет статистики капитала: структура активов в один клик&quot;">​</a></h2><p>Оперативный виджет статистики открывается по нажатию кнопки с пиктограммой аналитики на верхней панели инструментов вкладки <strong>«Деньги и инвестиции»</strong> (всплывающая подсказка <em>«Статистика и структура капитала»</em>).</p><p>Виджет спроектирован так, чтобы мастер мог мгновенно оценить структуру сбережений, не покидая текущего рабочего процесса:</p><div class="craft-window-frame" data-title="Статистика капитала"><div style="padding:1.25rem;"><div class="price-breakdown-card" style="margin-bottom:1.25rem;"><div class="breakdown-card-header"><span class="breakdown-badge">Валютная корзина</span><h4>4 850 000 ₽</h4></div><div class="breakdown-bar-track"><div class="breakdown-segment" style="width:64.9%;background:#3b82f6;" data-tooltip="Российский рубль (₽): 64.9% (3 150 000 ₽)"></div><div class="breakdown-segment" style="width:24.7%;background:#10b981;" data-tooltip="Доллар США ($): 24.7% (1 200 000 ₽)"></div><div class="breakdown-segment" style="width:10.4%;background:#f59e0b;" data-tooltip="Цифровой доллар (USDT): 10.4% (500 000 ₽)"></div></div><ul class="craft-feature-list" style="margin-top:0.75rem;"><li><span class="craft-list-bullet" style="background:#3b82f6;"></span><div><strong>Российский рубль (₽):</strong> 3 150 000 ₽ · 64,9%</div></li><li><span class="craft-list-bullet" style="background:#10b981;"></span><div><strong>Доллар США ($):</strong> 1 200 000 ₽ · 24,7%</div></li><li><span class="craft-list-bullet" style="background:#f59e0b;"></span><div><strong>Цифровой доллар (USDT):</strong> 500 000 ₽ · 10,4%</div></li></ul></div><div class="price-breakdown-card"><div class="breakdown-card-header"><span class="breakdown-badge">Классы активов</span><h4>9 400 000 ₽</h4></div><div class="breakdown-bar-track"><div class="breakdown-segment" style="width:38.8%;background:#06b6d4;" data-tooltip="Счета и кошельки: 38.8% (3 650 000 ₽)"></div><div class="breakdown-segment" style="width:12.8%;background:#8b5cf6;" data-tooltip="Инвестиционный портфель: 12.8% (1 200 000 ₽)"></div><div class="breakdown-segment" style="width:25.5%;background:#f59e0b;" data-tooltip="Имущество и активы: 25.5% (2 400 000 ₽)"></div><div class="breakdown-segment" style="width:22.9%;background:#3b82f6;" data-tooltip="Капитал мастерских: 22.9% (2 150 000 ₽)"></div></div><ul class="craft-feature-list" style="margin-top:0.75rem;"><li><span class="craft-list-bullet" style="background:#06b6d4;"></span><div><strong>Счета и кошельки:</strong> 3 650 000 ₽ · 38,8%</div></li><li><span class="craft-list-bullet" style="background:#8b5cf6;"></span><div><strong>Инвестиционный портфель:</strong> 1 200 000 ₽ · 12,8%</div></li><li><span class="craft-list-bullet" style="background:#f59e0b;"></span><div><strong>Имущество и активы:</strong> 2 400 000 ₽ · 25,5%</div></li><li><span class="craft-list-bullet" style="background:#3b82f6;"></span><div><strong>Капитал мастерских:</strong> 2 150 000 ₽ · 22,9%</div></li></ul></div></div></div><h3 id="форматы-отображения-выдвижная-шторка-или-модальныи-диалог" tabindex="-1">Форматы отображения: выдвижная шторка или модальный диалог <a class="header-anchor" href="#форматы-отображения-выдвижная-шторка-или-модальныи-диалог" aria-label="Permalink to &quot;Форматы отображения: выдвижная шторка или модальный диалог&quot;">​</a></h3><p>Интерфейс подстраивается под предпочтения создателя. В диалоге <strong>«Настройки пространства»</strong> (кнопка с шестеренкой на тулбаре) настраивается режим открытия виджета:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><rect width="18" height="18" x="3" y="3" rx="2"></rect><path d="M15 3v18"></path></svg></span><span><strong>Боковая выдвижная шторка (По умолчанию):</strong> Панель плавно выдвигается из правой границы экрана на фиксированную ширину, не перекрывая списки счетов и таблицу инвестиций. Это идеальный формат для широких мониторов: мастер может сверять валютную долю параллельно с распределением денег по вкладам. Закрывается кликом по крестику или по свободной области экрана.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><rect width="18" height="18" x="3" y="3" rx="2"></rect><path d="M9 9h6v6H9z"></path></svg></span><span><strong>Центрированное модальное окно:</strong> Компактное окно размером 520×520 пикселей, размещаемое по центру экрана. Фокусирует внимание на фундаментальных соотношениях цифр перед закрытием отчетного периода или совершением крупной сделки.</span></li></ul><div class="info custom-block"><p class="custom-block-title">Защита от пустых расчетов</p><p>Если в системе еще не создано ни одного счета с ненулевым сальдо, а базы данных производственных мастерских пусты, виджет отображает защитную заглушку <em>«Недостаточно данных для формирования статистики»</em>. Расчет активируется автоматически сразу после фиксации первых балансов.</p></div><hr><h2 id="валютная-корзина-математическая-защита-от-девальвации" tabindex="-1">Валютная корзина: Математическая защита от девальваций <a class="header-anchor" href="#валютная-корзина-математическая-защита-от-девальвации" aria-label="Permalink to &quot;Валютная корзина: Математическая защита от девальваций&quot;">​</a></h2><p>Инфляция и резкие курсовые скачки способны обесценить рублевую прибыль успешной мастерской за считанные недели. Чтобы предотвратить скрытые убытки, ОмниКрафт ЕРП рассчитывает <strong>валютную корзину создателя</strong>.</p><p>Алгоритм автоматически сканирует все активные (не отправленные в архив) счета мастера и все открытые позиции инвестиционного портфеля.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Алгоритм валютной корзины</span><div class="formula-heading">Расчет доли валюты в совокупной ликвидной массе</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Доля валюты (%)</span><span class="math-op">=</span><span class="math-group">(</span><span class="math-var">Сумма в валюте</span><span class="math-op">×</span><span class="math-var">Курс пересчета</span><span class="math-group">)</span><span class="math-op">/</span><span class="math-var">Общий ликвидный пул</span><span class="math-op">×</span><span class="math-num">100%</span></div></div><div class="formula-card-bottom"><p>Общий ликвидный пул включает остатки всех расчетных счетов, вкладов, наличных сейфов и текущую стоимость инвестиционных активов, приведенные к базовой валюте учета по действующим курсам.</p></div></div><h3 id="интерактивная-многосегментная-шкала" tabindex="-1">Интерактивная многосегментная шкала <a class="header-anchor" href="#интерактивная-многосегментная-шкала" aria-label="Permalink to &quot;Интерактивная многосегментная шкала&quot;">​</a></h3><p>В верхней части секции расположена цветная шкала долей. Каждый сегмент представляет отдельную валюту, а его ширина строго пропорциональна процентному весу в портфеле.</p><p>При наведении курсора на сегмент всплывает интерактивная подсказка с точным рублевым эквивалентом и процентной долей.</p><h3 id="детализированныи-реестр-валют" tabindex="-1">Детализированный реестр валют <a class="header-anchor" href="#детализированныи-реестр-валют" aria-label="Permalink to &quot;Детализированный реестр валют&quot;">​</a></h3><p>Ниже шкалы формируется подробный список валютных активов, отсортированный по убыванию рублевой массы:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Колонка реестра</th><th style="text-align:left;">Отображаемые данные</th><th style="text-align:left;">Физический смысл для мастера</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Наименование</strong></td><td style="text-align:left;">Официальное русскоязычное название и символ (например, <em>«Доллар США ($)»</em>)</td><td style="text-align:left;">Формируется строго по международному стандарту Юникод без сокращений и жаргонизмов.</td></tr><tr><td style="text-align:left;"><strong>Эквивалент</strong></td><td style="text-align:left;">Сумма в базовой расчетной валюте цеха (например, <em>«1 200 000,00 ₽»</em>)</td><td style="text-align:left;">Показывает фактическую покупательную способность данной валютной части капитала на внутреннем рынке.</td></tr><tr><td style="text-align:left;"><strong>Оригинал и вес</strong></td><td style="text-align:left;">Нативный баланс и процент (например, <em>«$ 12 500,00 · 24.7%»</em>)</td><td style="text-align:left;">Позволяет контролировать оригинальный номинал на зарубежном счете и его удельный вес в сбережениях.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Золотое правило валютной диверсификации мастера</p><p>Опытный ремесленник структурирует накопления по трем рубежам:</p><ol><li><strong>Операционный рубеж цеха (1–2 месяца работы):</strong> держится строго в валюте основных поставщиков материалов и фурнитуры для гарантии бесперебойных закупок;</li><li><strong>Семейный резерв безопасности (3–6 месяцев бытовых трат):</strong> формируется в стабильных твердых валютах и накопительных инструментах с ежедневным процентом;</li><li><strong>Капитал развития:</strong> распределяется между производственным оборудованием высокой ликвидности и диверсифицированным инвестиционным портфелем.</li></ol></div><hr><h2 id="четыре-класса-активов-балансировка-устоичивости" tabindex="-1">Четыре класса активов: балансировка устойчивости <a class="header-anchor" href="#четыре-класса-активов-балансировка-устоичивости" aria-label="Permalink to &quot;Четыре класса активов: балансировка устойчивости&quot;">​</a></h2><p>Если валютная корзина анализирует структуру денег и ценных бумаг, то блок <strong>«Классы активов»</strong> раскрывает полноту управленческого баланса мастера. Он распределяет совокупный капитал по четырем фундаментальным направлениям:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"></span><div><strong>Ликвидные счета (Бирюзовый):</strong><br> Свободные деньги на банковских картах, расчётных счетах, вкладах и в наличных сейфах. </div></li><li><span class="craft-list-bullet"></span><div><strong>Инвестиционный портфель (Фиолетовый):</strong><br> Облигации, акции, индексные фонды, процентные займы и цифровые активы. </div></li><li><span class="craft-list-bullet"></span><div><strong>Личное имущество (Янтарный):</strong><br> Недвижимость, земельные участки, автотранспорт с учётом персональной доли владения. </div></li><li><span class="craft-list-bullet"></span><div><strong>Капитал мастерских (Синий):</strong><br> Чистые коммерческие активы действующих производственных цехов и сервисных студий. </div></li></ul><h3 id="формула-совокупного-капитала-и-процентных-долеи" tabindex="-1">Формула совокупного капитала и процентных долей <a class="header-anchor" href="#формула-совокупного-капитала-и-процентных-долеи" aria-label="Permalink to &quot;Формула совокупного капитала и процентных долей&quot;">​</a></h3><p>Программа сопоставляет стоимость каждого класса с итоговой оценкой благосостояния:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Структура баланса</span><div class="formula-heading">Расчет удельного веса классов активов</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Доля фонда (%)</span><span class="math-op">=</span><span class="math-var">Балансовая стоимость класса</span><span class="math-op">/</span><span class="math-var">Абсолютный чистый капитал</span><span class="math-op">×</span><span class="math-num">100%</span></div></div><div class="formula-card-bottom"><p>Абсолютный капитал = Счета + Инвестиции + Личное имущество + Чистые активы мастерских. В стоимость мастерских входят остатки касс цехов, склад материалов по скользящей средней (МАК), склад готовой продукции по методу первых партий (ФИФО) и остаточная стоимость оборудования за вычетом амортизации.</p></div></div><h3 id="роли-и-функции-четырех-классов-капитала" tabindex="-1">Роли и функции четырех классов капитала <a class="header-anchor" href="#роли-и-функции-четырех-классов-капитала" aria-label="Permalink to &quot;Роли и функции четырех классов капитала&quot;">​</a></h3><p>Каждый класс активов решает собственную задачу в защите создателя от жизненных и производственных рисков:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Класс активов</th><th style="text-align:left;">Цветовой индикатор</th><th style="text-align:left;">Главная функция в портфеле</th><th style="text-align:left;">Риск при дисбалансе</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Счета и кошельки</strong></td><td style="text-align:left;">Бирюзовый (<code>Teal</code>)</td><td style="text-align:left;">Мгновенная ликвидность, покрытие срочных расходов, расчеты с поставщиками.</td><td style="text-align:left;">При избытке — скрытые потери от инфляции; при дефиците — кассовый разрыв.</td></tr><tr><td style="text-align:left;"><strong>Инвестиционный портфель</strong></td><td style="text-align:left;">Фиолетовый (<code>Violet</code>)</td><td style="text-align:left;">Обгон инфляции, получение пассивного дохода, рост капитала выше ключевой ставки.</td><td style="text-align:left;">При избытке — рыночные просадки в неподходящий момент; риск заморозки ликвидности.</td></tr><tr><td style="text-align:left;"><strong>Личные ресурсы и имущество</strong></td><td style="text-align:left;">Янтарный (<code>Amber</code>)</td><td style="text-align:left;">Долгосрочный материальный якорь семьи (жилье, транспорт, капитальные строения).</td><td style="text-align:left;">Низкая ликвидность: имущество невозможно оперативно продать по рыночной цене за один день.</td></tr><tr><td style="text-align:left;"><strong>Капитал рабочих пространств</strong></td><td style="text-align:left;">Синий (<code>Blue</code>)</td><td style="text-align:left;">Генератор операционного денежного потока, рабочие места, станки и материалы.</td><td style="text-align:left;">Риск концентрации: кризис в одной отрасли ставит под удар все благосостояние семьи.</td></tr></tbody></table><hr><h2 id="вкладка-«аналитика»-долгосрочные-тренды-и-финансовые-маяки" tabindex="-1">Вкладка «Аналитика»: Долгосрочные тренды и финансовые маяки <a class="header-anchor" href="#вкладка-«аналитика»-долгосрочные-тренды-и-финансовые-маяки" aria-label="Permalink to &quot;Вкладка «Аналитика»: Долгосрочные тренды и финансовые маяки&quot;">​</a></h2><p>В то время как виджет статистики показывает текущее состояние на сегодняшнюю секунду, отдельная вкладка <strong>«Аналитика»</strong> (пятая кнопка в переключателе подвкладок модуля «Мой капитал») спроектирована для стратегического анализа динамики развития.</p><p>В верхней части вкладки расположен системный заголовок <strong>«Аналитика и тренды»</strong>, информационный индикатор этапа дорожной карты и кнопка вызова справочной документации.</p><p>Ниже развернуты три аналитических карточки стратегического горизонта:</p><table class="craft-matrix-table"><thead><tr><th style="width:34%;">Динамика чистого капитала</th><th style="width:33%;">Структура активов</th><th style="width:33%;">Тренды расходов (Темп жизни)</th></tr></thead><tbody><tr><td><strong>Годовой тренд: +24,8%</strong><br>Помесячный рост с непрерывной историей капитала.</td><td><strong>4 класса фондов</strong><br>Визуальное соотношение ликвидности, инвестиций и цехов.</td><td><strong>По балансовой дельте</strong><br>Автоматический расчёт свободных трат семьи без чеков.</td></tr></tbody></table><ol><li><strong>Карточка «Динамика чистого капитала»:</strong><ul><li>Отслеживает помесячную траекторию роста совокупного богатства мастера;</li><li>Выводит расчетный годовой темп прироста капитала со знаком <code>+</code> изумрудного цвета;</li><li>Показывает, опережает ли развитие дела реальную инфляцию издержек.</li></ul></li><li><strong>Карточка «Структура распределения активов»:</strong><ul><li>Контролирует степень сбалансированности четырех классов фондов;</li><li>Помогает удерживать безопасные пропорции между производственными станками и личной денежной подушкой.</li></ul></li><li><strong>Карточка «Тренды свободных расходов»:</strong><ul><li>Отражает средний уровень семейных трат мастера в месяц;</li><li>Расчет строится на основе балансовой дельты капитала: система берет заработанную прибыль и вычитает реальный прирост денег на счетах и крупные целевые расходы, освобождая мастера от утомительного сбора кассовых чеков.</li></ul></li></ol><h3 id="начальное-состояние-вкладки-защитныи-экран" tabindex="-1">Начальное состояние вкладки (Защитный экран) <a class="header-anchor" href="#начальное-состояние-вкладки-защитныи-экран" aria-label="Permalink to &quot;Начальное состояние вкладки (Защитный экран)&quot;">​</a></h3><p>Если мастер только начал работу с ОмниКрафт ЕРП и еще не внес стартовые балансы, вкладка автоматически переходит в режим ожидания:</p><ul><li>Отображается приветственный блок с пояснением назначения аналитического модуля;</li><li>Выводится кнопка <strong>«+ Добавить счет»</strong> для быстрого старта с заведения первого банковского счета или наличного кошелька;</li><li>Доступна кнопка загрузки демонстрационных данных, позволяющая начинающему мастеру наглядно изучить работу графиков на готовом тренировочном примере.</li></ul><hr><h2 id="непрерывность-финансовои-ретроспективы-архитектурныи-закон" tabindex="-1">Непрерывность финансовой ретроспективы: Архитектурный закон <a class="header-anchor" href="#непрерывность-финансовои-ретроспективы-архитектурныи-закон" aria-label="Permalink to &quot;Непрерывность финансовой ретроспективы: Архитектурный закон&quot;">​</a></h2><p>Одной из самых разрушительных проблем традиционных систем финансового учета является потеря истории при закрытии подразделений. Если предприниматель продает столярный цех или закрывает направление сервисного ремонта и удаляет эту базу из программы, типовые таблицы теряют прошлые данные: графики прибыли за прошлые годы искажаются, а многолетний отчет о росте благосостояния семьи превращается в рваные обрывки.</p><p>В ОмниКрафт ЕРП на системном уровне реализован <strong>архитектурный инвариант непрерывности финансовой ретроспективы (Этап M5)</strong>.</p><div class="info custom-block"><p class="custom-block-title">Непрерывность финансовой ретроспективы (Этап M5)</p><p>ОмниКрафт ЕРП автоматически фиксирует помесячные статистические срезы ваших мастерских. Даже при закрытии или удалении старого пространства исторические графики не потеряют ни одного месяца.</p></div><h3 id="как-работает-консервация-исторических-слепков" tabindex="-1">Как работает консервация исторических слепков <a class="header-anchor" href="#как-работает-консервация-исторических-слепков" aria-label="Permalink to &quot;Как работает консервация исторических слепков&quot;">​</a></h3><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></span><span><strong>Автоматические помесячные слепки:</strong> В конце каждого календарного периода программа формирует снимок чистых активов и операционной прибыли каждого подключенного рабочего пространства.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" x2="12" y1="15" y2="3"></line></svg></span><span><strong>Изоляция от удаления баз данных:</strong> Если рабочее пространство выводится из эксплуатации и физически удаляется с диска, накопленные исторические снимки консервируются в главной базе данных пространства «Мой капитал».</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 6 13.5 15.5 8.5 10.5 1 18"></polyline><polyline points="17 6 23 6 23 12"></polyline></svg></span><span><strong>Неразрывность генерального графика:</strong> Аналитическая линия совокупного капитала за 3, 5 или 10 лет остается монолитной. Программа честно помнит каждый заработанный рубль, независимо от того, какие производственные юридические лица открывались и закрывались на этом пути.</span></li></ul><div class="info custom-block"><p class="custom-block-title">Физика учета: безопасность архивации</p><p>При удалении рабочего пространства через меню управления мастерскими система запрашивает подтверждение и выполняет финальный расчет чистых активов. Все завершенные расчеты навсегда остаются частью истории вашего семейного капитала.</p></div><hr><h2 id="диагностика-финансового-баланса-практическии-аудит-цеха" tabindex="-1">Диагностика финансового баланса: Практический аудит цеха <a class="header-anchor" href="#диагностика-финансового-баланса-практическии-аудит-цеха" aria-label="Permalink to &quot;Диагностика финансового баланса: Практический аудит цеха&quot;">​</a></h2><p>Регулярный просмотр виджета статистики позволяет вовремя обнаружить скрытые управленческие болезни бизнеса:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Симптом на шкале статистики</th><th style="text-align:left;">В чем заключается угроза</th><th style="text-align:left;">Решение мастера по цеху</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Капитал мастерских &gt; 70%, Счета &lt; 5%</strong></td><td style="text-align:left;">«Замороженный цех». Деньги заперты в тоннах кожи, дерева или станках. Любая задержка клиентской оплаты приведет к невозможности выдать зарплату или оплатить аренду.</td><td style="text-align:left;">Срочно остановить закупку сырья впрок, провести распродажу залежалых готовых изделий, пополнить кассовую подушку.</td></tr><tr><td style="text-align:left;"><strong>Валютная корзина: 100% рубли</strong></td><td style="text-align:left;">Высокий валютный риск. Если расходники или станки закупаются за рубежом, скачок курсов сделает новые закупки убыточными.</td><td style="text-align:left;">Перевести часть чистой прибыли в валюту закупок ключевых поставщиков (юани, доллары, стабильные цифровые активы).</td></tr><tr><td style="text-align:left;"><strong>Инвестиции &gt; 50% при отсутствии личной подушки</strong></td><td style="text-align:left;">Избыточный инвестиционный азарт. В случае непредвиденных семейных расходов мастер будет вынужден закрывать позиции в убыток на спаде рынка.</td><td style="text-align:left;">Сформировать неприкосновенный ликвидный денежный резерв на вкладах с быстрым доступом.</td></tr><tr><td style="text-align:left;"><strong>Личное имущество &gt; 80%</strong></td><td style="text-align:left;">Низкая мобильность капитала. Большая часть ресурсов связана в недвижимости или автомобилях, не приносящих операционного дохода.</td><td style="text-align:left;">Развивать производственные цепочки, увеличивать генерацию свободной чистой прибыли.</td></tr></tbody></table><hr><h2 id="вопросы-и-ответы-мастера" tabindex="-1">Вопросы и ответы мастера <a class="header-anchor" href="#вопросы-и-ответы-мастера" aria-label="Permalink to &quot;Вопросы и ответы мастера&quot;">​</a></h2><h3 id="как-часто-программа-обновляет-данные-в-виджете-статистики" tabindex="-1">Как часто программа обновляет данные в виджете статистики? <a class="header-anchor" href="#как-часто-программа-обновляет-данные-в-виджете-статистики" aria-label="Permalink to &quot;Как часто программа обновляет данные в виджете статистики?&quot;">​</a></h3><p>Расчет валютной корзины и долей классов активов происходит мгновенно при каждом открытии виджета или шторки. Программа считывает актуальные остатки счетов, текущие курсы валют и свежие балансы мастерских непосредственно из баз данных.</p><h3 id="что-происходит-со-статистикои-при-изменении-курса-валюты" tabindex="-1">Что происходит со статистикой при изменении курса валюты? <a class="header-anchor" href="#что-происходит-со-статистикои-при-изменении-курса-валюты" aria-label="Permalink to &quot;Что происходит со статистикой при изменении курса валюты?&quot;">​</a></h3><p>Если мастер меняет курс пересчета в диалоге <strong>«Курсы валют»</strong> (кнопка с двусторонней стрелкой на панели инструментов), все рублевые эквиваленты валютных счетов и инвестиций мгновенно пересчитываются. Доля валюты в корзине автоматически корректируется в соответствии с новой стоимостью.</p><h3 id="учитываются-ли-долги-при-расчете-классов-активов" tabindex="-1">Учитываются ли долги при расчете классов активов? <a class="header-anchor" href="#учитываются-ли-долги-при-расчете-классов-активов" aria-label="Permalink to &quot;Учитываются ли долги при расчете классов активов?&quot;">​</a></h3><p>Да. Если по личным счетам зафиксированы обязательства или кредитные карты с отрицательным сальдо, они уменьшают суммарную ликвидную массу денежного фонда. В производственных мастерских кредиторская задолженность перед поставщиками также уменьшает чистую балансовую стоимость цеха.</p>',64))])}const x=s(c,[["render",h]]);export{y as __pageData,x as default};
